public nonisolated func revalidateRecentSearchRows(_ source: [MailMessageSummary], text: String, filters: SearchFilters) async throws -> [MailMessageSummary] {
    try Task.checkCancellation()
    let plan = SearchQueryPlan(text:text,filters:filters)
    if !plan.text.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty, !Self.hasSearchableTerms(plan.text) { return [] }
    let fts = Self.escapedFTS(plan.text)
    let (scope,scopeArguments) = Self.searchScope(plan)
    let (strict,strictArguments) = Self.strictSearchConstraints(plan.text)
    let found = try await readSearch { [root] db in
        let decoder = Self.makeDecoder(root:root)
        var found: [String:MailMessageSummary] = [:]
        for start in stride(from:0,to:source.count,by:200) {
            try Task.checkCancellation()
            let ids = source[start..<min(start+200,source.count)].map(\.id)
            let placeholders = Array(repeating:"?",count:ids.count).joined(separator:",")
            let join = fts.isEmpty ? "" : " CROSS JOIN mail_fts f ON f.rowid=m.rowid"
            let match = fts.isEmpty ? "" : strict + " AND mail_fts MATCH ?"
            let arguments = ids.map(\.databaseValue) + scopeArguments + (fts.isEmpty ? [] : strictArguments + [fts.databaseValue])
            let sql = "WITH selected AS MATERIALIZED (SELECT rowid FROM messages WHERE id IN (" + placeholders + ")) SELECT " + Self.summaryProjection + " AS search_summary FROM selected CROSS JOIN messages m ON m.rowid=selected.rowid" + join + " WHERE " + scope + match
            let rows = try Self.fetchRows(db,name:"search_recent_refresh",sql:sql,arguments:StatementArguments(arguments))
            for row in rows {
                let json: String = row["search_summary"]
                let summary = try Self.measuredDecode(decoder,MailMessageSummary.self,from:Data(json.utf8))
                found[summary.id] = summary
            }
        }
        return found
    }
    try Task.checkCancellation()
    return source.compactMap { previous in
        guard let current = found[previous.id], current.accountID == previous.accountID,
              current.contentKey == previous.contentKey, current.receivedDate == previous.receivedDate else { return nil }
        return current
    }
}

