private func runBatch(presentation: MessageListPresentation?, _ action: @escaping @MainActor (MailMessageSummary) async -> Void) {
    guard model.isCurrentPresentation(presentation), !batchInFlight else { return }
    let messages = model.messages.filter { selectedIDs.contains($0.id) }
    batchInFlight = true
    Task {
        defer { batchInFlight = false }
        guard model.isCurrentPresentation(presentation) else { return }
        for message in messages { await action(message) }
        selectedIDs.removeAll(); isSelecting = false; explicitSelectionMode = false
        restorePadReaderFocusAfterBatch()
    }
}

