private func runBatchMove(to destination: MailFolder, presentation: MessageListPresentation?) {
    let messages = batchMessages
    guard model.isCurrentPresentation(presentation), !batchInFlight, model.canMoveBatch(messages, selectedIDs: selectedIDs, to: destination) else { return }
    batchInFlight = true
    Task {
        defer { batchInFlight = false }
        guard model.isCurrentPresentation(presentation) else { return }
        var failed = Set<String>()
        for message in messages {
            if !(await model.moveForBatch(message, to: destination.path)) { failed.insert(message.id) }
        }
        selectedIDs = failed.intersection(Set(model.messages.map(\.id)))
        isSelecting = !selectedIDs.isEmpty
        // Keep failed items selected for retry; leaving selection mode here
        // could expose a reader belonging to a different message.
        if !selectedIDs.isEmpty { explicitSelectionMode = true }
        if !isSelecting { explicitSelectionMode = false }
        if !isSelecting { restorePadReaderFocusAfterBatch() }
        if !failed.isEmpty { model.error = MailIssue(MailFailure.validationReason(.batchMoveFailed)) }
    }
}

func admitRowAction(_ action: MessageRowAction) -> Bool {
    guard !Task.isCancelled, isCurrentPresentation(action.presentation), action.presentation.scope.allows(account: action.accountID),
          !removingAccountIDs.contains(action.accountID) else { return false }
    return messages.contains { $0.id == action.id && $0.accountID == action.accountID && $0.contentKey == action.contentKey }
}

