def git(repo: Path, *args: str, timeout: int = 60) -> str:
    proc = run(["git", "-C", str(repo), *args], cwd=None, timeout=timeout)
    if proc.returncode != 0:
        raise GitError((proc.stderr.strip() or proc.stdout.strip() or "git command failed")[:2000])
    return proc.stdout.strip()

def pr_event(action: str, number: int, base: str, head: str,
             draft: bool = False, merged: bool = False,
             created: str = "9999-01-01T00:00:00Z",
             branch: str = "f") -> dict:
    state = "closed" if (action == "closed" or merged) else "open"
    return {"action": action, "repository": {"full_name": REPO},
            "pull_request": {
                "number": number, "state": state, "draft": draft,
                "merged": merged, "created_at": created,
                "base": {"sha": base}, "head": {"sha": head, "ref": branch}}}

def _live(*heads):
    """Scripted get_live_head: yields each head in order, then repeats."""
    calls = {"n": 0}

    def _fn(repo: str, pr_number: int):
        idx = min(calls["n"], len(heads) - 1)
        calls["n"] += 1
        return heads[idx]

    return _fn

